package info.fadl.mamalauncher.ui;
import android.view.*;import android.widget.*;import app.cash.paparazzi.*;import org.junit.*;import static org.junit.Assert.*;
public class FeedbackRenderTest {
 @Rule public final Paparazzi paparazzi=new Paparazzi(EnvironmentKt.detectEnvironment(),DeviceConfig.NEXUS_5,"MamaTheme");
 void measure(View v){v.measure(View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1620,View.MeasureSpec.EXACTLY));v.layout(0,0,1080,1620);}
 void clock(int direction,String name){View v=paparazzi.inflate(R.layout.activity_main);v.setLayoutDirection(direction);v.findViewById(R.id.first_use_guide).setVisibility(View.GONE);HomeClock.bind(v,new java.util.Date(0),java.util.TimeZone.getTimeZone("UTC"));LinearLayout tiles=v.findViewById(R.id.tiles_container);tiles.addView(UiBinder.buildHomeTile(v.getContext(),"الهاتف",v.getResources().getDrawable(R.drawable.ic_call),R.drawable.chip_green,false,null));measure(v);TextView period=v.findViewById(R.id.home_clock_period),digits=v.findViewById(R.id.home_clock);assertTrue(period.getRight()<digits.getLeft());assertTrue(period.getTextSize()<digits.getTextSize());assertEquals("ص",period.getText().toString());assertEquals("12:00",digits.getText().toString());paparazzi.snapshot(v,name);}
 @Test public void clockAndTileRtl(){clock(View.LAYOUT_DIRECTION_RTL,"feedback-home-rtl");}
 @Test public void clockAndTileLtr(){clock(View.LAYOUT_DIRECTION_LTR,"feedback-home-ltr");}
 @Test public void headerTrueCenterBothDirections(){for(int dir:new int[]{View.LAYOUT_DIRECTION_LTR,View.LAYOUT_DIRECTION_RTL}){View v=paparazzi.inflate(R.layout.activity_phone);v.setLayoutDirection(dir);((View)v.findViewById(R.id.page_title).getParent()).setLayoutDirection(dir);PageHeader.title(v,R.string.tile_phone);measure(v);View t=v.findViewById(R.id.page_title),p=(View)t.getParent();assertEquals(p.getWidth()/2f,(t.getLeft()+t.getRight())/2f,1f);paparazzi.snapshot(v,dir==View.LAYOUT_DIRECTION_RTL?"feedback-header-rtl":"feedback-header-ltr");}}
 @Test public void confirmPaddingBothDirections(){for(int dir:new int[]{View.LAYOUT_DIRECTION_LTR,View.LAYOUT_DIRECTION_RTL}){View v=paparazzi.inflate(R.layout.activity_confirm);v.setLayoutDirection(dir);v.findViewById(R.id.btn_call).setLayoutDirection(dir);v.findViewById(R.id.btn_back).setLayoutDirection(dir);((TextView)v.findViewById(R.id.big_name)).setText("اسم تجريبي");measure(v);for(int id:new int[]{R.id.btn_call,R.id.btn_back}){TextView b=v.findViewById(id);float d=v.getResources().getDisplayMetrics().density;assertTrue(b.getPaddingStart()>=23*d);assertTrue(b.getPaddingEnd()>=23*d);assertTrue(b.getHeight()>=48*d);}paparazzi.snapshot(v,dir==View.LAYOUT_DIRECTION_RTL?"feedback-padding-rtl":"feedback-padding-ltr");}}
 @Test public void settingsLockPreference(){View v=paparazzi.inflate(R.layout.activity_settings);SettingsSections.show(v,2);measure(v);v.findViewById(R.id.settings_section_accessibility).findViewById(R.id.switch_home_after_lock).requestFocus();((ScrollView)v.findViewById(R.id.settings_scroll)).setSmoothScrollingEnabled(false);((ScrollView)v.findViewById(R.id.settings_scroll)).fullScroll(View.FOCUS_DOWN);assertNotNull(v.findViewById(R.id.switch_home_after_lock));paparazzi.snapshot(v,"feedback-lock-setting");}

 @Test public void wrappedTitleKeepsBackVerticallyCentered(){
  View v=paparazzi.inflate(R.layout.page_header);TextView title=v.findViewById(R.id.page_title);title.setText("عنوان طويل\nفي سطرين");title.setTextSize(38);v.measure(View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1620,View.MeasureSpec.AT_MOST));v.layout(0,0,1080,v.getMeasuredHeight());
  assertEquals(LinearLayout.HORIZONTAL,((LinearLayout)v).getOrientation());View back=v.findViewById(R.id.btn_back);
  assertEquals(v.getHeight()/2f,(back.getTop()+back.getBottom())/2f,1f);paparazzi.snapshot(v,"feedback-header-wrapped");
 }
}
